import os
import re

# Search for all {{ placeholders }} in the template
base_dir = '/tmp/hwpx_work/template_contents'
placeholders_found = []

for root, dirs, files in os.walk(base_dir):
    for f in files:
        if f.endswith('.xml') or f == 'mimetype':
            continue
        full_path = os.path.join(root, f)
        try:
            with open(full_path, 'r', encoding='utf-8') as file:
                content = file.read()
                matches = re.findall(r'\{\{[^}]+\}\}', content)
                if matches:
                    rel_path = os.path.relpath(full_path, base_dir)
                    placeholders_found.append((rel_path, matches))
                    print(f"File: {rel_path}")
                    for m in matches:
                        print(f"  Found placeholder: {m}")
        except Exception as e:
            pass

# Also check XML files
for root, dirs, files in os.walk(base_dir):
    for f in files:
        if f.endswith('.xml'):
            full_path = os.path.join(root, f)
            try:
                with open(full_path, 'r', encoding='utf-8') as file:
                    content = file.read()
                    matches = re.findall(r'\{\{[^}]+\}\}', content)
                    if matches:
                        rel_path = os.path.relpath(full_path, base_dir)
                        placeholders_found.append((rel_path, matches))
                        print(f"\nFile: {rel_path}")
                        for m in matches:
                            print(f"  Found placeholder: {m}")
            except Exception as e:
                pass

print(f"\n\nTotal placeholder locations: {len(placeholders_found)}")

